  const stationRow = {"id":"A130600LSJHES","name":"錦湖國小","coordinates":[120.16886,23.296416],"date":"2025-12-31","height":25.36};
  // END official WRA data

  const features = contourRows.map(([kind, id, rawValue, coordinates]) => {
    const cumulative = kind === 'cumulative';
    const unit = cumulative ? '公分' : '公分/年';
    const value = -rawValue || 0;
    const label = cumulative ? `累積下陷 ${value} 公分等值線` : `平均下陷速率 ${value} 公分/年等值線`;
    return {
      type: 'Feature', id,
      geometry: {type: 'LineString', coordinates},
      properties: {
        kind, label, period: cumulative ? '2001–2023 年' : '2019–2023 年',
        value, rawValue, unit, sourceUrl: source[kind]
      }
    };
  });
  features.push({
    type: 'Feature', id: stationRow.id,
    geometry: {type: 'Point', coordinates: stationRow.coordinates},
    properties: {
      kind: 'station', label: `${stationRow.name} GNSS 測站高程 ${stationRow.height} 公尺`,
      period: stationRow.date, value: stationRow.height, rawValue: stationRow.height,
      unit: '公尺', sourceUrl: source.station, locationUrl: source.stationLocation
    }
  });

  function numericCoordinate(value) {
    if (typeof value === 'string' && value.trim()) return Number(value);
    return typeof value === 'number' ? value : NaN;
  }

  // Short local distances from a reference point to a line segment in kilometres.
  function featureDistance(feature, lat, lon, kmPerLon) {
    const kmPerLat = 111.2;
    const coords = feature.geometry.coordinates;
    if (feature.geometry.type === 'Point') {
      return Math.hypot((coords[0] - lon) * kmPerLon, (coords[1] - lat) * kmPerLat);
    }
    let shortest = Infinity;
    for (let i = 1; i < coords.length; i++) {
      const [prevLon, prevLat] = coords[i - 1];
      const x = (prevLon - lon) * kmPerLon, y = (prevLat - lat) * kmPerLat;
      const dx = (coords[i][0] - prevLon) * kmPerLon, dy = (coords[i][1] - prevLat) * kmPerLat;
      const length2 = dx * dx + dy * dy;
      const t = length2 ? Math.max(0, Math.min(1, -(x * dx + y * dy) / length2)) : 0;
      shortest = Math.min(shortest, (x + t * dx) ** 2 + (y + t * dy) ** 2);
    }
    return Math.sqrt(shortest);
  }

  function distanceText(km) {
    if (km < 0.01) return '不到 10 公尺';
    if (km < 1) return `約 ${Math.round(km * 100) * 10} 公尺`;
    return `約 ${km.toFixed(1)} 公里`;
  }

  function lookup(latitudeOrCommunity, longitude) {
    const community = typeof latitudeOrCommunity === 'object' && latitudeOrCommunity !== null
      ? latitudeOrCommunity : null;
    const lat = numericCoordinate(community ? community.lat : latitudeOrCommunity);
    const lon = numericCoordinate(community ? community.lon : longitude);
    const empty = (status, summary) => ({
      status, summary, nearest: null, distanceKm: null, byKind: {}, sourceUrl: source.county
    });
    if (!Number.isFinite(lat) || !Number.isFinite(lon) || !lat || !lon) {
      return empty('no_coordinates', '缺少社區定位，請以門牌或地號查詢水利署資料。');
    }
    if (lon < 120.02 || lon > 120.66 || lat < 22.88 || lat > 23.42) {
      return empty('outside_coverage', '座標超出本站臺南圖資查詢範圍，請核對位置。');
    }

    const location = {main: '主門牌推估點', nearby: '鄰近門牌推估點', exact: '門牌參考點'};
    const pointName = location[community?.positionEstimated] || '定位參考點';
    const kmPerLon = 111.2 * Math.cos(lat * Math.PI / 180);
    const byKind = {};
    for (const feature of features) {
      const {kind, label, period, sourceUrl} = feature.properties;
      const distanceKm = featureDistance(feature, lat, lon, kmPerLon);
      if (!byKind[kind] || distanceKm < byKind[kind].distanceKm) {
        byKind[kind] = {
          nearest: feature, distanceKm, sourceUrl,
          summary: `${pointName}距${period}的「${label}」${distanceText(distanceKm)}。`
        };
      }
    }
    const nearestContour = byKind.rate.distanceKm <= byKind.cumulative.distanceKm
      ? byKind.rate : byKind.cumulative;
    const approximate = ['nearby', 'main'].includes(community?.positionEstimated);
    return {
      ...nearestContour, byKind, status: approximate ? 'approximate' : 'reference_only',
      summary: nearestContour.summary + '線值只描述圖線，基地現況需另行勘測。'
    };
  }

  window.MapSubsidence = {features, lookup, source};
